function validate(input) {
  const [{ NewYork = [], California = [] }] = input;
  for (const [name, rows] of [['NewYork', NewYork], ['California', California]]) {
    const seen = new Set();
    for (const [id, score] of rows) {
      if (id === null) return `Every row of ${name} needs a student_id.`;
      if (seen.has(id)) return `student_id ${id} appears twice in ${name}.`;
      if (score === null) return `Student ${id} in ${name} needs a score.`;
      seen.add(id);
    }
  }
  return null;
}

