function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const table = () => {
    const count = size === 'small' ? Math.floor(rand() * 9) : 1500 + Math.floor(rand() * 501);
    const rows = [];
    for (let i = 0; i < count; i++) {
      // Small cases stay near the 90 boundary so ties and off-by-one thresholds show up.
      const score = size === 'small' ? pick([75, 88, 89, 90, 90, 91, 95, 100]) : Math.floor(rand() * 101);
      rows.push([i + 1 + (size === 'small' ? Math.floor(rand() * 2) * 10 : 0), score]);
    }
    return rows;
  };
  return [{ NewYork: table(), California: table() }];
}
